-- Modulo 69 Capacitaciones: catalogo de cursos, programaciones con cupo, inscripciones y certificaciones.
-- Spec: docs/specs/modulo69-capacitaciones-backend.md (§4).

CREATE TABLE "Cursos" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "Codigo" character varying(20) NOT NULL,
    "Nombre" character varying(150) NOT NULL,
    "Horas" numeric(5,1) NOT NULL,
    "Tipo" character varying(20) NOT NULL,
    "Proveedor" character varying(150),
    "Activo" boolean NOT NULL,
    CONSTRAINT "PK_Cursos" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_Cursos_Horas" CHECK ("Horas" > 0 AND "Horas" <= 500),
    CONSTRAINT "CK_Cursos_Tipo" CHECK ("Tipo" IN ('Interno', 'Externo', 'Virtual'))
);
CREATE UNIQUE INDEX "IX_Cursos_Codigo" ON "Cursos" ("Codigo");

CREATE TABLE "ProgramacionesCurso" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "CursoId" integer NOT NULL,
    "Anio" integer NOT NULL,
    "FechaInicio" date NOT NULL,
    "FechaFin" date NOT NULL,
    "Cupo" integer NOT NULL,
    "Lugar" character varying(150),
    "Estado" character varying(20) NOT NULL,
    CONSTRAINT "PK_ProgramacionesCurso" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ProgramacionesCurso_Cursos_CursoId" FOREIGN KEY ("CursoId") REFERENCES "Cursos" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_ProgramacionesCurso_Fechas" CHECK ("FechaFin" >= "FechaInicio"),
    CONSTRAINT "CK_ProgramacionesCurso_Cupo" CHECK ("Cupo" BETWEEN 1 AND 500),
    CONSTRAINT "CK_ProgramacionesCurso_Estado" CHECK ("Estado" IN ('Programada', 'Realizada', 'Cancelada'))
);
CREATE INDEX "IX_ProgramacionesCurso_CursoId" ON "ProgramacionesCurso" ("CursoId");
CREATE INDEX "IX_ProgramacionesCurso_Anio" ON "ProgramacionesCurso" ("Anio");

CREATE TABLE "InscripcionesCurso" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "ProgramacionCursoId" integer NOT NULL,
    "EmpleadoId" integer NOT NULL,
    "Estado" character varying(20) NOT NULL,
    "Nota" numeric(4,1),
    "FechaInscripcion" date NOT NULL,
    CONSTRAINT "PK_InscripcionesCurso" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_InscripcionesCurso_ProgramacionesCurso_ProgramacionCursoId" FOREIGN KEY ("ProgramacionCursoId") REFERENCES "ProgramacionesCurso" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_InscripcionesCurso_Empleados_EmpleadoId" FOREIGN KEY ("EmpleadoId") REFERENCES "Empleados" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_InscripcionesCurso_Estado" CHECK ("Estado" IN ('Inscrito', 'Aprobado', 'Desaprobado', 'Retirado')),
    CONSTRAINT "CK_InscripcionesCurso_Nota" CHECK ("Nota" IS NULL OR ("Nota" >= 0 AND "Nota" <= 20))
);
CREATE UNIQUE INDEX "IX_InscripcionesCurso_ProgramacionCursoId_EmpleadoId" ON "InscripcionesCurso" ("ProgramacionCursoId", "EmpleadoId");
CREATE INDEX "IX_InscripcionesCurso_EmpleadoId" ON "InscripcionesCurso" ("EmpleadoId");

CREATE TABLE "CertificacionesCurso" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "InscripcionCursoId" integer NOT NULL,
    "Codigo" character varying(40) NOT NULL,
    "FechaEmision" date NOT NULL,
    "FechaVencimiento" date,
    CONSTRAINT "PK_CertificacionesCurso" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_CertificacionesCurso_InscripcionesCurso_InscripcionCursoId" FOREIGN KEY ("InscripcionCursoId") REFERENCES "InscripcionesCurso" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_CertificacionesCurso_Fechas" CHECK ("FechaVencimiento" IS NULL OR "FechaVencimiento" >= "FechaEmision")
);
CREATE UNIQUE INDEX "IX_CertificacionesCurso_InscripcionCursoId" ON "CertificacionesCurso" ("InscripcionCursoId");
CREATE UNIQUE INDEX "IX_CertificacionesCurso_Codigo" ON "CertificacionesCurso" ("Codigo");
